def imports(path):
    out=[]
    for l in open(path,errors='replace'):
        mm=re.match(r'import\s+(\S+)',l)
        if mm: out.append(mm.group(1))
        elif l.strip() and not l.startswith('--') and not l.startswith('/-'): 
